function openPayment(id){syncFilters();$('paymentForm').reset();$('paymentId').value=id||'';$('invoiceMonth').value=monthKey(new Date());$('dueDate').value=new Date().toISOString().slice(0,10);$('paymentStatus').value='支払予定';const p=state.payments.find(x=>x.id===id);if(p){$('invoiceMonth').value=p.invoiceMonth;$('paymentDepartment').value=p.department;fillSectionOptions($('paymentSection'),p.department);$('paymentSection').value=p.section||'';$('paymentVendor').value=p.vendorId;$('invoiceDate').value=p.invoiceDate||'';$('dueDate').value=p.dueDate;$('paymentStatus').value=p.status;$('ediInfo').value=p.ediInfo||'';$('paymentNote').value=p.note||''}$('expenseLines').innerHTML='';(p?.lines?.length?p.lines:[{category:'仕入10%',amount:''}]).forEach(addExpenseLine);calcDialogTotal();$('paymentDialog').showModal()}
function addExpenseLine(line={}){const row=document.createElement('div');row.className='expense-line';row.innerHTML=`<select class="line-category">${categories.map(c=>`<option ${c===line.category?'selected':''}>${c}</option>`).join('')}</select><input class="line-amount" type="number" min="0" step="1" placeholder="金額" value="${line.amount??''}"><button type="button">×</button>`;row.querySelector('button').onclick=()=>{row.remove();calcDialogTotal()};row.querySelector('input').oninput=calcDialogTotal;row.querySelector('select').onchange=calcDialogTotal;$('expenseLines').append(row)}function getLines(){return [...document.querySelectorAll('.expense-line')].map(r=>({category:r.querySelector('.line-category').value,amount:Number(r.querySelector('.line-amount').value)||0})).filter(x=>x.amount>0)}function calcDialogTotal(){const lines=getLines(),gross=lines.filter(l=>categoryType(l.category)!=='deduction').reduce((s,l)=>s+l.amount,0),deductions=lines.filter(l=>categoryType(l.category)==='deduction').reduce((s,l)=>s+l.amount,0);$('paymentGross').textContent=yen(gross);$('paymentDeduction').textContent=`−${yen(deductions)}`;$('paymentTotal').textContent=yen(gross-deductions)}
