function eligibleTransfers(){const m=$('bankMonth').value,d=$('bankDepartment').value,grouped=new Map();state.payments.filter(p=>p.status==='支払予定'&&(!m||p.invoiceMonth===m)&&(!d||p.department===d)).forEach(p=>{const source=state.vendors.find(v=>v.id===p.vendorId);if(!source)return;const vendor={...source,bankNameKana:source.bankNameKana||resolveBankKana(source.bankCode),branchNameKana:source.branchNameKana||resolveBranchKana(source.bankCode,source.branchCode)};const current=grouped.get(p.vendorId)||{...p,amount:0,vendor,sections:[]};current.amount+=total(p);if(p.section&&!current.sections.includes(p.section))current.sections.push(p.section);if(!current.ediInfo&&p.ediInfo)current.ediInfo=p.ediInfo;grouped.set(p.vendorId,current)});return [...grouped.values()]}
