function initBatchAndDepartments(){
  const now=new Date(),currentMonth=monthKey(now),lastDay=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
  $('batchMonth').value=currentMonth;
  $('batchDueDate').value=`${currentMonth}-${String(lastDay).padStart(2,'0')}`;
  syncFilters();
  $('quickAdd').onclick=()=>showView('batch');
  $('batchMonth').onchange=renderBatch;
  $('batchDepartment').onchange=renderBatch;
  $('batchDueDate').onchange=()=>document.querySelectorAll('.batch-due').forEach(input=>{if(!input.dataset.edited)input.value=$('batchDueDate').value});
  $('batchRows').oninput=e=>{if(e.target.classList.contains('batch-amount')){e.target.value=formatAmount(e.target.value);calcBatchTotal()}else if(e.target.classList.contains('batch-category'))calcBatchTotal();if(e.target.classList.contains('batch-due'))e.target.dataset.edited='1'};
  $('batchRows').onkeydown=e=>{if(!e.target.classList.contains('batch-amount')||!['Enter','Tab'].includes(e.key))return;e.preventDefault();const inputs=[...document.querySelectorAll('#batchRows .batch-amount')],index=inputs.indexOf(e.target),nextIndex=e.shiftKey?index-1:index+1;if(inputs[nextIndex]){inputs[nextIndex].focus();inputs[nextIndex].select()}else if(e.shiftKey)$('batchVendorPicker').focus();else $('saveBatch').focus()};
  $('batchRows').onclick=e=>{if(e.target.dataset.batchEdit)openPayment(e.target.dataset.batchEdit)};
  $('saveBatch').onclick=saveBatch;
  $('vendorForm').onsubmit=e=>{
    e.preventDefault();
    const departments=[...document.querySelectorAll('#vendorDepartments input:checked')].map(c=>c.value);
    if(!departments.length)return toast('対象部署を1つ以上選択してください');
    const id=$('vendorId').value||uid(),old=state.vendors.find(v=>v.id===id);
    const vendor={id,name:$('vendorName').value,departments,bankCode:$('vendorBankCode').value,bankName:$('vendorBankName').value,branchCode:$('vendorBranchCode').value,branchName:$('vendorBranchName').value,accountType:$('vendorAccountType').value,accountNumber:$('vendorAccountNumber').value,recipientName:$('vendorRecipientName').value};
    state.vendors=old?state.vendors.map(v=>v.id===id?vendor:v):[...state.vendors,vendor];
    state.payments.forEach(p=>{if(p.vendorId===id)p.vendorName=vendor.name});
    save();syncFilters();$('vendorDialog').close();renderVendors();toast('取引先を保存しました');
  };
}
