    const vendor=state.vendors.find(v=>v.id===$('paymentVendor').value);if(!vendor)return toast('取引先を選択してください');
    const id=$('paymentId').value||uid(),old=state.payments.find(p=>p.id===id),payment={id,invoiceMonth:$('invoiceMonth').value,department,section,vendorId:vendor.id,vendorName:vendor.name,invoiceDate:$('invoiceDate').value,dueDate:$('dueDate').value,status:$('paymentStatus').value,ediInfo:$('ediInfo').value,note:$('paymentNote').value,lines,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
